import triton
import triton.language as tl

_MAX_DIMS = 8
_SLOTS = 16

_UNSUPPORTED_MSG = "\"foreach\" not implemented for '{}'"


@triton.jit
def _sigmoid_flat_kernel(x_ptr, n_elements, BLOCK: tl.constexpr):
    """Unit-stride fast path: flat index == logical index."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements
    x = tl.load(x_ptr + offs, mask=mask, other=0.0).to(tl.float32)
    y = 1.0 / (1.0 + tl.exp2(x * -1.4426950408889634))
    tl.store(x_ptr + offs, y.to(x_ptr.dtype.element_ty), mask=mask)


