@triton.jit
def _sigmoid_strided_kernel(
    x_ptr,
    n_elements,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    t0,
    t1,
    t2,
    t3,
    t4,
    t5,
    t6,
    t7,
    ND: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """General dense-view path.

    Dimensions are collapsed and ordered slowest -> fastest, so the last
    (fastest varying) dimension carries the unit stride for the common
    transpose/permute/slice views.
    """
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements
    rem = offs.to(tl.int64)
    off = tl.zeros((BLOCK,), dtype=tl.int64)
    if ND > 0:
        off += (rem % s0) * t0
        rem = rem // s0
    if ND > 1:
        off += (rem % s1) * t1
        rem = rem // s1
    if ND > 2:
        off += (rem % s2) * t2
        rem = rem // s2
    if ND > 3:
        off += (rem % s3) * t3
        rem = rem // s3
    if ND > 4:
        off += (rem % s4) * t4
        rem = rem // s4
    if ND > 5:
        off += (rem % s5) * t5
        rem = rem // s5
    if ND > 6:
        off += (rem % s6) * t6
        rem = rem // s6
    if ND > 7:
        off += (rem % s7) * t7
        rem = rem // s7
    x = tl.load(x_ptr + off, mask=mask, other=0.0).to(tl.float32)
    y = 1.0 / (1.0 + tl.exp(-x))
    tl.store(x_ptr + off, y.to(x_ptr.dtype.element_ty), mask=mask)


def _pick_block(n):
    """Task-derived tile size (elements per program)."""
    if n <= 32768:
        return 1024
    if n <= 262144:
        return 2048
    if n <= 2097152:
        return 4096
    return 8192


def _collapse(sizes, strides):
    """Drop size-1 dims, merge adjacent dims, order slowest -> fastest."""
    dims = [(int(s), int(st)) for s, st in zip(sizes, strides) if s != 1]
    merged = []
    for s, st in dims:
        if merged and merged[-1][1] == s * st:
            ps, pst = merged[-1]
            merged[-1] = (ps * s, st)
        else:
            merged.append((s, st))
    # Slowest varying (largest stride) first; the unit-stride dim ends last.
    return sorted(merged, key=lambda d: -d[1])


def _launch_strided(t):
    n = t.numel()
    if n == 0:
        return
    block = _pick_block(n)
    grid = (triton.cdiv(n, block),)
    dims = _collapse(t.shape, t.stride())
    nd = len(dims)
    if nd > _MAX_DIMS:
        raise RuntimeError("foreach_sigmoid_: too many dims for strided kernel")
    sizes = [1] * _MAX_DIMS
    strides = [0] * _MAX_DIMS
    for i, (s, st) in enumerate(dims):
        sizes[i] = s
        strides[i] = st
    _sigmoid_strided_kernel[grid](
        t,
        n,
        sizes[0],
        sizes[1],
        sizes[2],
        sizes[3],
        sizes[4],
        sizes[5],
        sizes[6],
        sizes[7],
        strides[0],
        strides[1],
        strides[2],
        strides[3],
        strides[4],
        strides[5],
        strides[6],
        strides[7],
        nd,
        block,
    )


def _launch_group(group):
    """One launch for a run of contiguous same-dtype tensors."""
    nt = len(group)
    if nt == 1:
        t = group[0]
        n = t.numel()
        block = _pick_block(n)
        _sigmoid_flat_kernel[(triton.cdiv(n, block),)](t, n, block)
        return

    numels = []
    total = 0
    for t in group:
        numels.append(t.numel())
    block = _pick_block(max(numels))
    for n in numels:
        total += (n + block - 1) // block
    ptrs = [t.data_ptr() for t in group]
    first = ptrs[0]
    while len(ptrs) < _SLOTS:
        ptrs.append(first)
        numels.append(0)
    _sigmoid_multi_kernel[(total,)](
        ptrs[0],
        ptrs[1],
        ptrs[2],
        ptrs[3],
        ptrs[4],
        ptrs[5],
        ptrs[6],
        ptrs[7],
        ptrs[8],
        ptrs[9],
        ptrs[10],
        ptrs[11],
        ptrs[12],
        ptrs[13],
        ptrs[14],
        ptrs[15],
        numels[0],
        numels[1],
        numels[2],
        numels[3],
        numels[4],
        numels[5],
        numels[6],
        numels[7],
        numels[8],
        numels[9],
        numels[10],
        numels[11],
        numels[12],
        numels[13],
        numels[14],
        numels[15],
        _TL_DT[group[0].dtype],
        block,
    )


_TL_DT = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
    torch.float64: tl.float64,
}


def _bad_dtype_contract(dtype):
    """Cold path: reproduce the reference refusal for a non-float dtype."""
    if dtype.is_complex:
        raise RuntimeError(_UNSUPPORTED_MSG.format(str(dtype).replace("torch.", "")))
    raise RuntimeError(
        "result type {} can't be cast to the desired output type {}".format(
            "Float", str(dtype).replace("torch.", "").capitalize()
        )
    )


def foreach_sigmoid_(self):
    if not isinstance(self, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    tensors = list(self)
    if len(tensors) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")

    # One classification pass: validate every element and record the launch
    # plan without touching any data, so no kernel runs before the whole list
    # has been checked.  A plan entry is either a list of contiguous same-dtype
    # tensors (fused into one launch) or a bare tensor (strided, one launch).
    plan = []
    group = []
    gdt = None
    for t in tensors:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        dt = t.dtype
        if not dt.is_floating_point:
            _bad_dtype_contract(dt)
        if t.is_contiguous():
            if t.numel():
                if group and dt != gdt:
                    plan.append(group)
                    group = []
                gdt = dt
                group.append(t)
                if len(group) == _SLOTS:
                    plan.append(group)
                    group = []
                    gdt = None
        else:
            if group:
                plan.append(group)
                group = []
                gdt = None
            if torch._debug_has_internal_overlap(t) == 1:
                raise RuntimeError(
                    "unsupported operation: more than one element of the "
                    "written-to tensor refers to a single memory location. "
                    "Please clone() the tensor before performing the operation."
                )
            plan.append(t)
    if group:
        plan.append(group)

    for item in plan:
        if isinstance(item, list):
            _launch_group(item)
        else:
            _launch_strided(item)
    return None
